// Confere o formulário e cria o código do app (ex.: "barbearia-do-ze-k3f9").
let b = $('🔔 Pedido de criação (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b-\u001f\u007f<>]/g, ' ').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const slug = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 40);
const crypto = require('crypto');

const dados = {
  nome: limpa(b.nome, 60),
  tipo: limpa(b.tipo, 40),
  sobre: limpa(b.sobre, 1200),
  whatsapp: String(b.whatsapp || '').replace(/\D/g, '').slice(0, 15),
  instagram: limpa(b.instagram, 40).replace(/^@/, '').replace(/[^a-zA-Z0-9._]/g, ''),
  endereco: limpa(b.endereco, 200),
  horario: limpa(b.horario, 300),
  produtos: limpa(b.produtos, 3000),
  promocao: limpa(b.promocao, 300),
  cor: /^#[0-9a-fA-F]{6}$/.test(b.cor || '') ? b.cor : '',
};
const erros = [];
if (dados.nome.length < 2) erros.push('Digite o nome do negócio.');
if (dados.whatsapp.length < 10) erros.push('Digite o WhatsApp com DDD.');
if (dados.produtos.length < 3 && dados.sobre.length < 10) erros.push('Conte um pouco sobre o negócio ou liste os produtos/serviços.');
if (dados.whatsapp.length >= 10 && dados.whatsapp.length <= 11) dados.whatsapp = '55' + dados.whatsapp;

const id = (slug(dados.nome) || 'app') + '-' + crypto.randomBytes(3).toString('hex').slice(0, 4);
const chave = crypto.randomBytes(6).toString('hex');
const hora = new Date().toISOString().slice(0, 13);
const base = String($('🔔 Pedido de criação (POST)').first().json.webhookUrl || '').split('/webhook/')[0] + '/webhook';
return [{ json: { valido: erros.length === 0, erros, id, chave, dados, chave_limite: '<SEGREDO_REMOVIDO>' + hora,
  app_url: `${base}/app/${id}/inicio`, painel_url: `${base}/app-painel?id=${id}&chave=${chave}` } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Junta o que o dono digitou com o que a IA criou. Se a IA falhar, o app sai mesmo assim (versão simples).
const base = $('🧩 Confere o pedido').first().json;
const d = base.dados;
const crypto = require('crypto');
let ia = null;
try { ia = parseJSON($('🤖 Diretor do app').first().json.output); } catch (e) {}
ia = ia || {};

const txt = (v, max) => String(v ?? '').replace(/[<>]/g, '').trim().slice(0, max);
const corOk = c => /^#[0-9a-fA-F]{6}$/.test(c || '');
const PALETA = { restaurante: '#c2410c', lanchonete: '#c2410c', barbearia: '#1f2937', salao: '#be185d', loja: '#7c3aed', clinica: '#0e7490', saude: '#0e7490', servicos: '#1d4ed8', academia: '#15803d' };
const tipoSlug = d.tipo.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const corPadrao = Object.entries(PALETA).find(([k]) => tipoSlug.includes(k))?.[1] || '#1c5cab';

// Catálogo: da IA; se não vier, cada linha "Produto - R$ 10" vira um item
let catalogo = Array.isArray(ia.catalogo) ? ia.catalogo : [];
catalogo = catalogo.slice(0, 8).map(c => ({
  categoria: txt(c.categoria, 40) || 'Destaques',
  itens: (Array.isArray(c.itens) ? c.itens : []).slice(0, 20).map(i => ({
    nome: txt(i.nome, 60), descricao: txt(i.descricao, 120), emoji: txt(i.emoji, 4),
    preco: Number(String(i.preco ?? '').replace(/[^\d,.]/g, '').replace(/\.(?=\d{3}\b)/g, '').replace(',', '.')) || 0,
  })).filter(i => i.nome),
})).filter(c => c.itens.length);
if (!catalogo.length && d.produtos) {
  const itens = d.produtos.split(/\n|;/).map(l => l.trim()).filter(Boolean).slice(0, 30).map(l => {
    const m = l.match(/^(.*?)[\s\-–:]*R?\$?\s*(\d+[\d.,]*)\s*$/);
    return { nome: txt(m ? m[1] : l, 60), descricao: '', emoji: '', preco: m ? Number(m[2].replace(/\.(?=\d{3}\b)/g, '').replace(',', '.')) || 0 : 0 };
  }).filter(i => i.nome);
  if (itens.length) catalogo = [{ categoria: 'Produtos e serviços', itens }];
}

// Horários: [{dias:[0..6], abre:"08:00", fecha:"18:00"}] (0 = domingo)
const hhmm = v => (/^\d{1,2}:\d{2}$/.test(String(v || '')) ? String(v).padStart(5, '0') : '');
const horarios = (Array.isArray(ia.horarios) ? ia.horarios : []).map(h => ({
  dias: (Array.isArray(h.dias) ? h.dias : []).map(Number).filter(n => n >= 0 && n <= 6), abre: hhmm(h.abre), fecha: hhmm(h.fecha),
})).filter(h => h.dias.length && h.abre && h.fecha).slice(0, 7);

// Chaves das notificações (VAPID): cada app tem as suas, geradas aqui
const { privateKey, publicKey } = crypto.generateKeyPairSync('ec', { namedCurve: 'prime256v1' });
const jwk = privateKey.export({ format: 'jwk' });
const pub = publicKey.export({ format: 'jwk' });
const b64u = buf => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const unb = s => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64');
const vapidPublica = b64u(Buffer.concat([Buffer.from([4]), unb(pub.x), unb(pub.y)]));

const palavras = d.nome.split(/\s+/).filter(p => p.length > 2 || /^[A-Z0-9]/.test(p));
const iniciais = ((palavras[0] || d.nome)[0] + (palavras[1] ? palavras[1][0] : (palavras[0] || '').slice(1, 2))).toUpperCase().replace(/[^A-Z0-9ÁÉÍÓÚÂÊÔÃÕÇ]/g, '') || 'AP';

const app = {
  id: base.id, chave: base.chave, criado_em: new Date().toISOString(), feito_com_ia: !!ia.slogan,
  nome: d.nome, nome_curto: txt(ia.nome_curto, 12) || d.nome.slice(0, 12), tipo: d.tipo,
  slogan: txt(ia.slogan, 90) || d.tipo || 'Bem-vindo!',
  sobre: txt(ia.sobre, 500) || d.sobre,
  destaques: (Array.isArray(ia.destaques) ? ia.destaques : []).slice(0, 3).map(x => ({ emoji: txt(x.emoji, 4), titulo: txt(x.titulo, 40), texto: txt(x.texto, 110) })).filter(x => x.titulo),
  catalogo,
  horarios, horario_texto: d.horario,
  promocao: (ia.promocao && ia.promocao.titulo) ? { titulo: txt(ia.promocao.titulo, 60), texto: txt(ia.promocao.texto, 160) }
    : (d.promocao ? { titulo: 'Promoção', texto: d.promocao } : null),
  faq: (Array.isArray(ia.faq) ? ia.faq : []).slice(0, 5).map(f => ({ p: txt(f.p, 100), r: txt(f.r, 300) })).filter(f => f.p && f.r),
  mensagem_whatsapp: txt(ia.mensagem_whatsapp, 140) || `Olá! Vim pelo app da ${d.nome}.`,
  cor: corOk(d.cor) ? d.cor : (corOk(ia.cor) ? ia.cor : corPadrao), iniciais: iniciais.slice(0, 2),
  whatsapp: d.whatsapp, instagram: d.instagram, endereco: d.endereco,
  vapid: { publica: vapidPublica, privada: { kty: 'EC', crv: 'P-256', d: jwk.d, x: jwk.x, y: jwk.y } },
};
return [{ json: { id: app.id, app: JSON.stringify(app) } }];

// Desenha a tela do app (o que o cliente instala no celular).
const id = String(($('🔔 Abrir app (GET)').first().json.params || {}).id || '');
let app = null;
try { app = JSON.parse($('📖 Lê o app').first().json.app || 'null'); } catch (e) {}
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

if (!app) {
  return [{ json: { codigo: 404, html: `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>App não encontrado</title></head>
<body style="font-family:system-ui,sans-serif;display:grid;place-items:center;min-height:100vh;margin:0;background:#f6f6f4;color:#222;text-align:center;padding:24px">
<div><div style="font-size:56px">📱</div><h1 style="font-size:22px">App não encontrado</h1><p style="color:#666">Confira o link que você recebeu.</p></div></body></html>` } }];
}

// Cores derivadas da cor principal
const hex = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));
const paraHex = a => '#' + a.map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('');
const mistura = (c, alvo, t) => paraHex(hex(c).map((v, i) => v + (alvo[i] - v) * t));
const lum = c => { const [r, g, b] = hex(c).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }); return 0.2126 * r + 0.7152 * g + 0.0722 * b; };
const C = app.cor;
const corTexto = lum(C) > 0.45 ? '#111111' : '#ffffff';
const C2 = mistura(C, [0, 0, 0], 0.35), CL = mistura(C, [255, 255, 255], 0.9), CLd = mistura(C, [0, 0, 0], 0.55);
// Cor muito escura some no modo escuro (e muito clara some no claro): calcula versões legíveis (contraste mínimo 4,5)
const contraste = (a, b) => { const x = lum(a), y = lum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const legivel = (fundo, para, alvo = 4.5) => { let x = C; for (let t = 0.05; t <= 1.01 && contraste(x, fundo) < alvo; t += 0.05) x = mistura(C, para, t); return x; };
const destaqueClaro = legivel('#ffffff', [0, 0, 0]), destaqueEscuro = legivel('#1b1b1d', [255, 255, 255]);
const botaoEscuro = contraste(C, '#1b1b1d') < 3 ? legivel('#1b1b1d', [255, 255, 255], 8) : C;
const textoBotaoEscuro = lum(botaoEscuro) > 0.45 ? '#111111' : '#ffffff';
const brl = n => n ? Number(n).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }) : '';
const wa = msg => `https://wa.me/${app.whatsapp}?text=${encodeURIComponent(msg)}`;
const mapa = app.endereco ? 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(app.endereco) : '';

const acoes = [
  ['💬', 'WhatsApp', wa(app.mensagem_whatsapp), 'whatsapp'],
  ['📞', 'Ligar', 'tel:+' + app.whatsapp, 'ligar'],
  mapa && ['📍', 'Como chegar', mapa, 'mapa'],
  app.instagram && ['📸', 'Instagram', 'https://instagram.com/' + app.instagram, 'instagram'],
].filter(Boolean);

const catalogoHtml = app.catalogo.map(c => `<section class="cat"><h3>${esc(c.categoria)}</h3>
${c.itens.map(i => `<article class="item" data-busca="${esc((i.nome + ' ' + i.descricao).toLowerCase())}">
<div class="em">${esc(i.emoji || '•')}</div><div class="info"><b>${esc(i.nome)}</b>${i.descricao ? `<small>${esc(i.descricao)}</small>` : ''}${i.preco ? `<span class="preco">${brl(i.preco)}</span>` : ''}</div>
<a class="pedir" data-ev="pedido" href="${esc(wa(`Olá! Quero: ${i.nome}${i.preco ? ' (' + brl(i.preco) + ')' : ''}`))}" target="_blank" rel="noopener">Pedir</a></article>`).join('')}</section>`).join('');

const DIAS = ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'];
const horariosHtml = app.horarios.length
  ? DIAS.map((nome, d) => { const h = app.horarios.find(x => x.dias.includes(d)); return `<li data-dia="${d}"><span>${nome}</span><span>${h ? h.abre + ' – ' + h.fecha : 'Fechado'}</span></li>`; }).join('')
  : (app.horario_texto ? `<li><span>${esc(app.horario_texto)}</span></li>` : '');

// Este código roda no celular do cliente (vai como texto com .toString()).
function cliente(APP) {
  var el = function (s) { return document.querySelector(s); };
  var BASE = '/webhook';
  function envia(evento, extra) {
    try { fetch(BASE + '/app-evento', { method: 'POST', headers: { 'Content-Type': 'text/plain' }, keepalive: true,
      body: JSON.stringify(Object.assign({ id: APP.id, evento: evento }, extra || {})) }); } catch (e) {}
  }
  function toast(t) { var x = el('#toast'); x.textContent = t; x.classList.add('on'); setTimeout(function () { x.classList.remove('on'); }, 3200); }
  var standalone = matchMedia('(display-mode: standalone)').matches || navigator.standalone === true;
  envia('abriu', { modo: standalone ? 'app' : 'navegador' });

  // Aberto agora?
  function status() {
    var agora = new Date(), d = agora.getDay(), min = agora.getHours() * 60 + agora.getMinutes();
    var hoje = (APP.horarios || []).find(function (h) { return h.dias.indexOf(d) > -1; });
    var li = document.querySelector('li[data-dia="' + d + '"]'); if (li) li.classList.add('hoje');
    if (!APP.horarios || !APP.horarios.length) return;
    var p = el('#status'), aberto = false;
    if (hoje) { var a = hoje.abre.split(':'), f = hoje.fecha.split(':'); aberto = min >= a[0] * 60 + +a[1] && min < f[0] * 60 + +f[1]; }
    p.textContent = aberto ? '● Aberto agora · fecha às ' + hoje.fecha : (hoje && min < hoje.abre.split(':')[0] * 60 + +hoje.abre.split(':')[1] ? '● Fechado · abre às ' + hoje.abre : '● Fechado agora');
    p.className = 'status ' + (aberto ? 'ab' : 'fe');
  }
  status();

  // Abas de baixo
  function aba(nome) {
    document.querySelectorAll('.tela').forEach(function (t) { t.hidden = t.id !== 'tela-' + nome; });
    document.querySelectorAll('nav.baixo button').forEach(function (b) { b.classList.toggle('on', b.dataset.aba === nome); });
    scrollTo(0, 0);
  }
  document.querySelectorAll('[data-aba]').forEach(function (b) { b.addEventListener('click', function () { aba(b.dataset.aba); }); });
  if (location.hash === '#catalogo') aba('catalogo');

  // Busca no catálogo
  var busca = el('#busca');
  if (busca) busca.addEventListener('input', function () {
    var q = busca.value.toLowerCase().trim();
    document.querySelectorAll('.item').forEach(function (i) { i.hidden = q && i.dataset.busca.indexOf(q) === -1; });
    document.querySelectorAll('.cat').forEach(function (c) { c.hidden = !c.querySelector('.item:not([hidden])'); });
  });
  document.addEventListener('click', function (e) { var a = e.target.closest('[data-ev]'); if (a) envia('clique', { tipo: a.dataset.ev }); });

  // Service worker = o que transforma a página em app (ícone, offline e notificações)
  if ('serviceWorker' in navigator) navigator.serviceWorker.register('sw').catch(function () {});

  // Instalar
  var pedidoInstalar = null, caixa = el('#instalar');
  var ios = /iphone|ipad|ipod/i.test(navigator.userAgent);
  window.addEventListener('beforeinstallprompt', function (e) { e.preventDefault(); pedidoInstalar = e; caixa.hidden = false; });
  if (!standalone && ios) { caixa.hidden = false; el('#instalar-txt').innerHTML = 'No iPhone: toque em <b>Compartilhar</b> <span class="ic">⬆️</span> e depois em <b>Adicionar à Tela de Início</b>.'; el('#bt-instalar').hidden = true; }
  el('#bt-instalar').addEventListener('click', function () {
    if (!pedidoInstalar) { toast('Abra o menu do navegador (⋮) e toque em "Instalar app".'); return; }
    pedidoInstalar.prompt(); pedidoInstalar.userChoice.then(function (r) { if (r.outcome === 'accepted') caixa.hidden = true; pedidoInstalar = null; });
  });
  window.addEventListener('appinstalled', function () { caixa.hidden = true; envia('instalou'); toast('App instalado! 🎉'); });
  if (standalone) caixa.hidden = true;

  // Notificações (Web Push)
  function chaveBytes(b64) { var p = '='.repeat((4 - b64.length % 4) % 4), s = atob((b64 + p).replace(/-/g, '+').replace(/_/g, '/')), a = new Uint8Array(s.length); for (var i = 0; i < s.length; i++) a[i] = s.charCodeAt(i); return a; }
  var btAvisos = el('#bt-avisos');
  function marcaAtivo() { btAvisos.textContent = '✅ Avisos ligados'; btAvisos.disabled = true; }
  if ('Notification' in window && Notification.permission === 'granted' && localStorage.getItem('avisos-' + APP.id)) marcaAtivo();
  btAvisos.addEventListener('click', function () {
    if (!('serviceWorker' in navigator) || !('PushManager' in window) || !('Notification' in window)) {
      toast(ios ? 'No iPhone, instale o app na Tela de Início e abra por ele para ligar os avisos.' : 'Este navegador não aceita avisos.'); return;
    }
    Notification.requestPermission().then(function (perm) {
      if (perm !== 'granted') { toast('Os avisos não foram liberados.'); return; }
      btAvisos.textContent = '⏳ Ligando…'; btAvisos.disabled = true;
      // Se o serviço de avisos do celular não responder em 15 s, desiste e deixa tentar de novo
      var limite = new Promise(function (_, falha) { setTimeout(function () { falha(new Error('tempo')); }, 15000); });
      return Promise.race([navigator.serviceWorker.ready.then(function (reg) {
        return reg.pushManager.getSubscription().then(function (s) { return s || reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: chaveBytes(APP.vapid) }); });
      }), limite]).then(function (sub) {
        envia('push', { sub: sub.toJSON() });
        try { localStorage.setItem('avisos-' + APP.id, '1'); } catch (e) {}
        marcaAtivo(); toast('Pronto! Você vai receber as novidades. 🔔');
      });
    }).catch(function (e) { btAvisos.textContent = '🔔 Ativar'; btAvisos.disabled = false; toast('Não deu para ligar os avisos agora. Tente de novo em instantes.'); });
  });
}

const html = `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>${esc(app.nome)}</title><meta name="description" content="${esc(app.slogan)}">
<link rel="manifest" href="manifest"><meta name="theme-color" content="${C}">
<link rel="icon" href="icone?t=192"><link rel="apple-touch-icon" href="icone?t=180">
<meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="${esc(app.nome_curto)}">
<style>
:root{--marca:${C};--marcat:${corTexto};--c:${C};--c2:${C2};--cl:${CL};--ct:${corTexto};--ca:${destaqueClaro};--tx:#18181b;--tx2:#52525b;--mu:#8a8a93;--fundo:#f6f6f4;--card:#fff;--borda:rgba(0,0,0,.08)}
@media (prefers-color-scheme:dark){:root{--c:${botaoEscuro};--ct:${textoBotaoEscuro};--ca:${destaqueEscuro};--cl:${CLd};--tx:#f4f4f5;--tx2:#c4c4cc;--mu:#8a8a93;--fundo:#0f0f10;--card:#1b1b1d;--borda:rgba(255,255,255,.09)}}
*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}
body{font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;background:var(--fundo);color:var(--tx);line-height:1.45;padding-bottom:calc(76px + env(safe-area-inset-bottom))}
header.topo{position:sticky;top:0;z-index:5;background:var(--marca);color:var(--marcat);padding:calc(12px + env(safe-area-inset-top)) 16px 12px;display:flex;align-items:center;gap:12px;box-shadow:0 2px 10px rgba(0,0,0,.12)}
header.topo img{width:42px;height:42px;border-radius:12px;box-shadow:0 0 0 2px rgba(255,255,255,.35)}
header.topo h1{font-size:18px;font-weight:700;line-height:1.15}
.status{font-size:12.5px;font-weight:600;opacity:.95}
.status.ab{color:${corTexto === '#ffffff' ? '#b8f7c6' : '#0a6b2b'}}.status.fe{opacity:.8}
main{max-width:640px;margin:0 auto;padding:16px}
.tela[hidden]{display:none}
.hero{background:linear-gradient(135deg,var(--marca),var(--c2));color:var(--marcat);border-radius:20px;padding:22px 20px;box-shadow:0 8px 24px rgba(0,0,0,.12)}
.hero h2{font-size:23px;line-height:1.2}.hero p{opacity:.9;margin-top:8px;font-size:15px}
.promo{margin-top:14px;background:var(--card);border:2px dashed var(--ca);border-radius:16px;padding:14px 16px}
.promo b{display:block;color:var(--ca);font-size:13px;letter-spacing:.04em;text-transform:uppercase}.promo p{margin-top:2px;font-size:16px;font-weight:600}
.acoes{display:grid;grid-template-columns:repeat(${acoes.length},1fr);gap:10px;margin-top:14px}
.acoes a{background:var(--card);border:1px solid var(--borda);border-radius:16px;padding:12px 4px;text-align:center;text-decoration:none;color:var(--tx);font-size:12.5px;font-weight:600}
.acoes a span{display:grid;place-items:center;width:44px;height:44px;margin:0 auto 6px;border-radius:50%;background:var(--cl);font-size:22px}
h3.tit{font-size:16px;margin:22px 0 10px}
.dest{display:grid;gap:10px}
.dest div{background:var(--card);border:1px solid var(--borda);border-radius:16px;padding:14px;display:flex;gap:12px;align-items:flex-start}
.dest i{font-style:normal;font-size:24px}.dest b{display:block}.dest small{color:var(--tx2);font-size:14px}
.caixa{margin-top:14px;background:var(--card);border:1px solid var(--borda);border-radius:16px;padding:14px 16px;display:flex;gap:12px;align-items:center}
.caixa p{flex:1;font-size:14px;color:var(--tx2)}.caixa p b{color:var(--tx)}
