.bt[disabled]{opacity:.7}
#busca{width:100%;font:inherit;font-size:16px;padding:12px 14px;border-radius:14px;border:1px solid var(--borda);background:var(--card);color:var(--tx);margin-bottom:6px}
.cat h3{font-size:15px;margin:18px 0 8px;color:var(--tx2)}
.item{background:var(--card);border:1px solid var(--borda);border-radius:16px;padding:12px;display:flex;gap:12px;align-items:center;margin-bottom:8px}
.item[hidden],.cat[hidden]{display:none}
.em{width:46px;height:46px;flex:none;border-radius:12px;background:var(--cl);display:grid;place-items:center;font-size:24px}
.info{flex:1;min-width:0}.info b{display:block;font-size:15px}.info small{display:block;color:var(--tx2);font-size:13px}
.preco{display:inline-block;margin-top:3px;font-weight:700;color:var(--ca)}
.pedir{flex:none;background:var(--c);color:var(--ct);text-decoration:none;font-weight:700;font-size:13.5px;padding:9px 13px;border-radius:11px}
.bloco{background:var(--card);border:1px solid var(--borda);border-radius:16px;padding:16px;margin-top:12px}
.bloco p{color:var(--tx2);font-size:15px}
ul.hor{list-style:none}ul.hor li{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid var(--borda);font-size:14.5px}
ul.hor li.hoje{font-weight:700;color:var(--ca)}
details{border-bottom:1px solid var(--borda);padding:10px 0}summary{font-weight:600;cursor:pointer}details p{margin-top:6px}
nav.baixo{position:fixed;left:0;right:0;bottom:0;z-index:6;background:var(--card);border-top:1px solid var(--borda);display:flex;padding:6px 6px calc(6px + env(safe-area-inset-bottom))}
nav.baixo button,nav.baixo a{flex:1;border:0;background:none;color:var(--mu);font:inherit;font-size:11.5px;font-weight:600;display:flex;flex-direction:column;align-items:center;gap:2px;padding:6px 0;text-decoration:none;cursor:pointer}
nav.baixo .ic{font-size:21px;line-height:1}
nav.baixo .on{color:var(--ca)}
#toast{position:fixed;left:50%;bottom:calc(86px + env(safe-area-inset-bottom));transform:translateX(-50%) translateY(20px);opacity:0;background:#18181b;color:#fff;padding:11px 16px;border-radius:12px;font-size:14px;transition:.25s;z-index:9;width:max-content;max-width:calc(100% - 32px);text-align:center}
#toast.on{opacity:1;transform:translateX(-50%) translateY(0)}
.rodape{text-align:center;color:var(--mu);font-size:12px;margin:26px 0 6px}
</style></head><body>
<header class="topo"><img src="icone?t=192" alt=""><div><h1>${esc(app.nome)}</h1><div class="status" id="status">${esc(app.tipo)}</div></div></header>
<main>
<section class="tela" id="tela-inicio">
  <div class="hero"><h2>${esc(app.slogan)}</h2>${app.sobre ? `<p>${esc(app.sobre.slice(0, 160))}${app.sobre.length > 160 ? '…' : ''}</p>` : ''}</div>
  ${app.promocao ? `<div class="promo"><b>🔥 ${esc(app.promocao.titulo)}</b><p>${esc(app.promocao.texto)}</p></div>` : ''}
  <div class="acoes">${acoes.map(([ic, rot, url, ev]) => `<a href="${esc(url)}" data-ev="${ev}" ${url.startsWith('http') ? 'target="_blank" rel="noopener"' : ''}><span>${ic}</span>${rot}</a>`).join('')}</div>
  <div class="caixa" id="instalar" hidden><p id="instalar-txt"><b>Instale o app</b> e tenha a gente sempre na tela do seu celular.</p><button class="bt" id="bt-instalar">📲 Instalar</button></div>
  <div class="caixa"><p><b>Receba as promoções</b> direto no celular, sem precisar de WhatsApp.</p><button class="bt" id="bt-avisos">🔔 Ativar</button></div>
  ${app.destaques.length ? `<h3 class="tit">Por que escolher a gente</h3><div class="dest">${app.destaques.map(x => `<div><i>${esc(x.emoji)}</i><span><b>${esc(x.titulo)}</b><small>${esc(x.texto)}</small></span></div>`).join('')}</div>` : ''}
  ${app.catalogo.length ? `<div class="caixa"><p><b>Veja o catálogo</b> com preços e peça em 1 toque.</p><button class="bt" data-aba="catalogo">🛍️ Abrir</button></div>` : ''}
</section>
<section class="tela" id="tela-catalogo" hidden>
  <input id="busca" type="search" placeholder="🔎 Buscar no catálogo" autocomplete="off">
  ${catalogoHtml || '<p class="bloco">O catálogo ainda está vazio.</p>'}
</section>
<section class="tela" id="tela-sobre" hidden>
  <div class="bloco"><h3 style="margin-bottom:6px">Sobre</h3><p>${esc(app.sobre || app.slogan)}</p></div>
  ${horariosHtml ? `<div class="bloco"><h3 style="margin-bottom:6px">🕒 Horário</h3><ul class="hor">${horariosHtml}</ul></div>` : ''}
  ${app.endereco ? `<div class="bloco"><h3 style="margin-bottom:6px">📍 Endereço</h3><p>${esc(app.endereco)}</p><p style="margin-top:10px"><a class="bt" style="display:inline-block;text-decoration:none" data-ev="mapa" href="${esc(mapa)}" target="_blank" rel="noopener">Abrir no mapa</a></p></div>` : ''}
  ${app.faq.length ? `<div class="bloco"><h3 style="margin-bottom:4px">❓ Perguntas frequentes</h3>${app.faq.map(f => `<details><summary>${esc(f.p)}</summary><p>${esc(f.r)}</p></details>`).join('')}</div>` : ''}
  <p class="rodape">App criado com IA no n8n</p>
</section>
</main>
<nav class="baixo">
  <button data-aba="inicio" class="on"><span class="ic">🏠</span>Início</button>
  <button data-aba="catalogo"><span class="ic">🛍️</span>Catálogo</button>
  <a href="${esc(wa(app.mensagem_whatsapp))}" data-ev="whatsapp" target="_blank" rel="noopener"><span class="ic">💬</span>WhatsApp</a>
  <button data-aba="sobre"><span class="ic">ℹ️</span>Sobre</button>
</nav>
<div id="toast" role="status"></div>
<script>(${cliente.toString()})(${JSON.stringify({ id: app.id, horarios: app.horarios, vapid: app.vapid.publica }).replace(/</g, '\\u003c')});</script>
</body></html>`;
return [{ json: { codigo: 200, html } }];

// Monta o service worker: o "motor" do app que fica no celular (guarda as telas para abrir sem internet e mostra as notificações).
const id = String(($('🔔 Pedido do motor (GET)').first().json.params || {}).id || '').replace(/[^a-z0-9-]/g, '');

function motor(ID) {
  var CACHE = 'app-' + ID + '-v1';
  var TELAS = ['inicio', 'manifest', 'icone?t=192', 'icone?t=512'];
  self.addEventListener('install', function (e) {
    e.waitUntil(caches.open(CACHE).then(function (c) { return c.addAll(TELAS); }).then(function () { return self.skipWaiting(); }));
  });
  self.addEventListener('activate', function (e) {
    e.waitUntil(caches.keys().then(function (ks) {
      return Promise.all(ks.filter(function (k) { return k.indexOf('app-' + ID + '-') === 0 && k !== CACHE; }).map(function (k) { return caches.delete(k); }));
    }).then(function () { return self.clients.claim(); }));
  });
  // Internet primeiro (pega novidades); sem internet, usa o que está guardado
  self.addEventListener('fetch', function (e) {
    var url = new URL(e.request.url);
    if (e.request.method !== 'GET' || url.origin !== location.origin || url.pathname.indexOf(self.registration.scope.replace(location.origin, '')) !== 0) return;
    e.respondWith(fetch(e.request).then(function (r) {
      if (r.ok) { var copia = r.clone(); caches.open(CACHE).then(function (c) { c.put(e.request, copia); }); }
      return r;
    }).catch(function () {
      return caches.match(e.request, { ignoreSearch: url.pathname.slice(-6) === 'inicio' }).then(function (r) { return r || caches.match('inicio'); });
    }));
  });
  // Notificação chegando
  self.addEventListener('push', function (e) {
    var d = {};
    try { d = e.data ? e.data.json() : {}; } catch (x) { d = { texto: e.data ? e.data.text() : '' }; }
    e.waitUntil(self.registration.showNotification(d.titulo || 'Novidade!', {
      body: d.texto || '', icon: 'icone?t=192', badge: 'icone?t=96', tag: d.tag || 'aviso', data: { url: d.url || 'inicio' },
    }));
  });
  self.addEventListener('notificationclick', function (e) {
    e.notification.close();
    var alvo = new URL(e.notification.data && e.notification.data.url || 'inicio', self.registration.scope).href;
    e.waitUntil(Promise.all([
      fetch('/webhook/app-evento', { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: JSON.stringify({ id: ID, evento: 'clique_aviso' }) }).catch(function () {}),
      self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(function (ws) {
        for (var i = 0; i < ws.length; i++) { if (ws[i].url.indexOf(self.registration.scope) === 0 && 'focus' in ws[i]) { ws[i].navigate(alvo); return ws[i].focus(); } }
        return self.clients.openWindow(alvo);
      }),
    ]));
  });
}
return [{ json: { js: id ? `(${motor.toString()})(${JSON.stringify(id)});` : '/* app inválido */' } }];

// O "RG" do app: nome, ícone e cor que o celular usa ao instalar.
let app = null;
try { app = JSON.parse($('📖 Lê o app (manifesto)').first().json.app || 'null'); } catch (e) {}
if (!app) return [{ json: { codigo: 404, manifesto: '{}' } }];
const atalhos = [{ name: 'Catálogo', short_name: 'Catálogo', url: 'inicio#catalogo', icons: [{ src: 'icone?t=96', sizes: '96x96' }] }];
const m = {
  id: 'app-' + app.id, name: app.nome, short_name: app.nome_curto, description: app.slogan, lang: 'pt-BR',
  start_url: 'inicio?origem=app', scope: './', display: 'standalone', orientation: 'portrait',
  background_color: app.cor, theme_color: app.cor,
  icons: [
    { src: 'icone?t=192', sizes: '192x192', type: 'image/png', purpose: 'any' },
    { src: 'icone?t=512', sizes: '512x512', type: 'image/png', purpose: 'any' },
    { src: 'icone?t=512&m=1', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
  ],
  shortcuts: atalhos,
};
return [{ json: { codigo: 200, manifesto: JSON.stringify(m) } }];

// Calcula o ícone: fundo na cor do negócio + iniciais centralizadas.
// "m=1" é o ícone que o Android recorta em círculo/gota (as letras ficam menores para não serem cortadas).
const q = $('🔔 Pedido do ícone (GET)').first().json.query || {};
let app = null;
try { app = JSON.parse($('📖 Lê o app (ícone)').first().json.app || 'null'); } catch (e) {}
const t = [96, 144, 180, 192, 512].includes(Number(q.t)) ? Number(q.t) : 192;
const recorte = q.m === '1';
const ini = (app ? app.iniciais : '?').slice(0, 2);
const fonte = Math.round(t * (recorte ? 0.3 : 0.4) * (ini.length === 1 ? 1.15 : 1));
const largura = fonte * 0.74 * ini.length; // Verdana Bold: cada letra maiúscula ocupa ~0,74 da altura
return [{ json: {
  tamanho: t, cor: app ? app.cor : '#1c5cab', iniciais: ini, fonte,
  x: Math.round((t - largura) / 2), y: Math.round(t / 2 + fonte * 0.36),
  // faixa decorativa embaixo (só no ícone normal)
  faixaY: recorte ? t : Math.round(t * 0.86), corFaixa: 'rgba(255,255,255,0.18)',
} }];

// Separa o que aconteceu no app: aberturas, instalações, cliques e quem ligou os avisos.
let b = $('🔔 Evento do app (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const id = String(b.id || '');
const EVENTOS = ['abriu', 'instalou', 'clique', 'push', 'clique_aviso'];
if (!/^[a-z0-9-]{4,60}$/.test(id) || !EVENTOS.includes(b.evento)) return [];
const dia = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' });
const k = s => `appst:${id}:${s}`;
const saida = [];
const soma = chave => saida.push({ json: { op: 'somar', chave } });

if (b.evento === 'abriu') { soma(k('abriu')); soma(k('abriu:' + dia)); if (b.modo === 'app') soma(k('abriu_app')); }
if (b.evento === 'instalou') soma(k('instalou'));
if (b.evento === 'clique') { const t = String(b.tipo || '').replace(/[^a-z_]/g, '').slice(0, 20) || 'outro'; soma(k('clique:' + t)); }
if (b.evento === 'clique_aviso') soma(k('clique_aviso'));
if (b.evento === 'push') {
  const s = b.sub || {};
  const ok = typeof s.endpoint === 'string' && /^https:\/\//.test(s.endpoint) && s.endpoint.length < 1000 && s.keys && s.keys.p256dh && s.keys.auth;
  if (ok) {
    const hash = require('crypto').createHash('sha256').update(s.endpoint).digest('hex').slice(0, 16);
    saida.push({ json: { op: 'guardar', chave: `apppush:${id}:${hash}`, valor: JSON.stringify({ endpoint: s.endpoint, keys: { p256dh: s.keys.p256dh, auth: s.keys.auth } }) } });
    soma(k('ativou_avisos'));
  }
}
return saida;

// Painel do dono: link e QR do app, números, promoção e envio de notificações.
const q = $('🔔 Painel do dono (GET)').first().json.query || {};
const base = String($('🔔 Painel do dono (GET)').first().json.webhookUrl || '').split('/webhook/')[0];
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const num = n => Number(n || 0).toLocaleString('pt-BR');
let app = null;
try { app = JSON.parse($('📖 Lê o app (painel)').first().json.app || 'null'); } catch (e) {}
// Botão principal legível nos dois modos (cor muito escura some no fundo escuro)
const hex = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));
const lum = c => { const [r, g, bb] = hex(c).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }); return 0.2126 * r + 0.7152 * g + 0.0722 * bb; };
const contraste = (x, y) => (Math.max(lum(x), lum(y)) + 0.05) / (Math.min(lum(x), lum(y)) + 0.05);
const mistura = (c, alvo, t) => '#' + hex(c).map((v, i) => Math.round(v + (alvo[i] - v) * t).toString(16).padStart(2, '0')).join('');
const COR = app ? app.cor : '#1c5cab';
let corEscuro = COR; for (let t = 0.1; t <= 1.01 && contraste(corEscuro, '#1a1a1c') < 3; t += 0.1) corEscuro = mistura(COR, [255, 255, 255], t);
const txt = c => (lum(c) > 0.45 ? '#111111' : '#ffffff');
const casca = (titulo, corpo) => `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(titulo)}</title>
<style>
:root{color-scheme:light;--plano:#f6f6f4;--sup:#fff;--tx:#18181b;--tx2:#52525b;--mu:#8a8a93;--borda:rgba(0,0,0,.09);--grid:#e4e4e0;--s1:#2a78d6;--ok:#0a7d34;--c:${COR};--ct:${txt(COR)}}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){color-scheme:dark;--plano:#0e0e0f;--sup:#1a1a1c;--tx:#f4f4f5;--tx2:#c4c4cc;--borda:rgba(255,255,255,.1);--grid:#2c2c2e;--s1:#3987e5;--ok:#5fd38a;--c:${corEscuro};--ct:${txt(corEscuro)}}}
:root[data-theme="dark"]{color-scheme:dark;--plano:#0e0e0f;--sup:#1a1a1c;--tx:#f4f4f5;--tx2:#c4c4cc;--borda:rgba(255,255,255,.1);--grid:#2c2c2e;--s1:#3987e5;--ok:#5fd38a;--c:${corEscuro};--ct:${txt(corEscuro)}}
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;background:var(--plano);color:var(--tx);line-height:1.45;padding:24px 16px 60px}
.w{max-width:980px;margin:0 auto}
.topo{display:flex;gap:14px;align-items:center}.topo img{width:56px;height:56px;border-radius:14px}
h1{font-size:23px}h2{font-size:15.5px;margin-bottom:8px}.sub{color:var(--tx2);font-size:14px}
.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:12px;margin-top:16px}
.card{background:var(--sup);border:1px solid var(--borda);border-radius:16px;padding:16px 18px}
.c3{grid-column:span 3}.c4{grid-column:span 4}.c5{grid-column:span 5}.c6{grid-column:span 6}.c7{grid-column:span 7}.c8{grid-column:span 8}.c12{grid-column:span 12}
.lab{color:var(--tx2);font-size:13px;font-weight:600}.val{font-size:30px;font-weight:700;margin-top:2px;font-variant-numeric:tabular-nums}.det{color:var(--mu);font-size:12.5px}
.link{display:flex;gap:16px;align-items:center;flex-wrap:wrap}.link img{width:150px;height:150px;border-radius:10px;background:#fff;padding:6px}
code.cod{display:block;background:var(--plano);border:1px solid var(--borda);border-radius:10px;padding:10px 12px;font:13px/1.5 ui-monospace,Consolas,monospace;word-break:break-all}
.bts{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
.btn{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--borda);background:var(--sup);color:var(--tx);font:inherit;font-weight:600;font-size:14px;padding:9px 14px;border-radius:11px;text-decoration:none;cursor:pointer}
.btn.pri{background:var(--c);color:var(--ct);border-color:transparent}
label{display:block;font-weight:600;font-size:13.5px;margin-top:10px}
input,textarea{width:100%;font:inherit;font-size:15px;padding:10px 12px;border-radius:10px;border:1px solid var(--borda);background:var(--plano);color:var(--tx);margin-top:4px}
textarea{min-height:70px;resize:vertical}
.res{margin-top:10px;font-size:14px;font-weight:600}
.cols{display:flex;align-items:flex-end;gap:3px;height:140px;border-bottom:1px solid var(--grid);margin-top:14px;padding-top:16px}
.col{flex:1;height:100%;display:flex;align-items:flex-end;justify-content:center;position:relative}
.col i{display:block;width:min(22px,70%);background:var(--s1);border-radius:4px 4px 0 0;outline:none}
.col em{position:absolute;font-style:normal;font-size:11.5px;font-weight:600}
.xl{display:flex;gap:3px;margin-top:5px}.xl span{flex:1;text-align:center;color:var(--mu);font-size:10.5px}
table{width:100%;border-collapse:collapse;font-size:13.5px}td,th{text-align:left;padding:7px 6px;border-bottom:1px solid var(--grid)}
ol{margin:6px 0 0 18px;color:var(--tx2);font-size:14px}ol li{margin-top:4px}
#tip{position:fixed;pointer-events:none;background:var(--tx);color:var(--sup);font-size:12.5px;padding:5px 8px;border-radius:7px;display:none;z-index:9}
@media(max-width:820px){.c3{grid-column:span 6}.c4,.c5,.c6,.c7,.c8{grid-column:span 12}}
</style></head><body><div class="w">${corpo}</div><div id="tip"></div></body></html>`;

if (!app || String(q.chave || '') !== app.chave) {
  return [{ json: { codigo: 403, html: casca('Painel do app', '<div class="card" style="max-width:420px;margin:80px auto;text-align:center"><div style="font-size:46px">🔒</div><h1>Link do painel inválido</h1><p class="sub">Use o link completo que apareceu quando o app foi criado.</p></div>') } }];
}

const pre = `appst:${app.id}:`;
const c = {};
for (const [k, v] of Object.entries($('🗂️ Lê os números').first().json || {})) if (k.startsWith(pre)) c[k.slice(pre.length)] = Number(v) || 0;
const inscritos = Object.keys($('🗂️ Lê os inscritos').first().json || {}).filter(k => k.startsWith('apppush:')).length;
let historico = [];
try { historico = JSON.parse($('📖 Lê o histórico (painel)').first().json.historico || '[]'); } catch (e) {}

const fuso = { timeZone: 'America/Sao_Paulo' };
const dias = [];
for (let i = 13; i >= 0; i--) {
  const d = new Date(Date.now() - i * 86400000);
  dias.push({ rot: d.toLocaleDateString('pt-BR', { ...fuso, day: '2-digit', month: '2-digit' }), v: c['abriu:' + d.toLocaleDateString('sv-SE', fuso)] || 0 });
}
const max = Math.max(1, ...dias.map(d => d.v));
const sete = dias.slice(-7).reduce((s, d) => s + d.v, 0);
const appUrl = `${base}/webhook/app/${app.id}/inicio`;
const cliquesZap = (c['clique:whatsapp'] || 0) + (c['clique:pedido'] || 0);

function cliente(ID, CHAVE) {
  var el = function (s) { return document.querySelector(s); };
  function envia(dados, res) {
    res.textContent = '⏳ Enviando…';
    return fetch('/webhook/app-painel-acao', { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: JSON.stringify(Object.assign({ id: ID, chave: CHAVE }, dados)) })
      .then(function (r) { return r.json(); }).catch(function () { return { ok: false, erro: 'Falha de conexão.' }; });
  }
  el('#f-aviso').addEventListener('submit', function (e) {
    e.preventDefault(); var res = el('#r-aviso');
    envia({ acao: 'notificar', titulo: el('#a-tit').value, texto: el('#a-txt').value }, res).then(function (r) {
      if (!r.ok) { res.textContent = '⚠️ ' + (r.erro || 'Não foi possível enviar.'); return; }
