      if (!r.ok) { res.textContent = '⚠️ ' + (r.erro || 'A IA não respondeu.'); return; }
      el('#a-tit').value = r.titulo; el('#a-txt').value = r.texto; res.textContent = '✨ Sugestão da IA. Ajuste se quiser e envie.';
