    });
  });
  document.addEventListener('click', function (e) {
    var b = e.target.closest('[data-copiar]'); if (!b) return;
    navigator.clipboard.writeText(el(b.dataset.copiar).textContent).then(function () { b.textContent = '✅ Copiado'; });
  });
  var t = el('#tip');
  document.addEventListener('mouseover', function (e) { var x = e.target.closest('[data-tip]'); if (!x) { t.style.display = 'none'; return; } t.textContent = x.dataset.tip; t.style.display = 'block'; var r = x.getBoundingClientRect(); t.style.left = Math.max(8, r.left + r.width / 2 - t.offsetWidth / 2) + 'px'; t.style.top = (r.top - t.offsetHeight - 6) + 'px'; });
}

