// Prepara uma notificação para CADA celular inscrito.
// Cada mensagem vai criptografada só para aquele celular (padrão Web Push, RFC 8291)
// e assinada com a chave do app (VAPID, RFC 8292), senão o Google/Apple/Mozilla recusam.
const crypto = require('crypto');
const pedido = $('🧩 Confere a chave e o pedido').first().json;
const app = pedido.app;
const bruto = $input.first().json || {};
const inscritos = Object.entries(bruto).filter(([k]) => k.startsWith('apppush:')).map(([chave, v]) => {
  try { return { chave, sub: JSON.parse(v) }; } catch (e) { return null; }
}).filter(Boolean);
if (!inscritos.length) return [{ json: { vazio: true } }];

const b64u = buf => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const unb = s => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64');

function criptografa(sub, texto) {
  const uaPublica = unb(sub.keys.p256dh), segredo = unb(sub.keys.auth);
  const ecdh = crypto.createECDH('prime256v1'); ecdh.generateKeys();
  const asPublica = ecdh.getPublicKey();
  const compartilhado = ecdh.computeSecret(uaPublica);
  const sal = crypto.randomBytes(16);
  const info = Buffer.concat([Buffer.from('WebPush: info\0'), uaPublica, asPublica]);
  const ikm = Buffer.from(crypto.hkdfSync('sha256', compartilhado, segredo, info, 32));
  const cek = Buffer.from(crypto.hkdfSync('sha256', ikm, sal, Buffer.from('Content-Encoding: aes128gcm\0'), 16));
  const nonce = Buffer.from(crypto.hkdfSync('sha256', ikm, sal, Buffer.from('Content-Encoding: nonce\0'), 12));
  const c = crypto.createCipheriv('aes-128-gcm', cek, nonce);
  const cifrado = Buffer.concat([c.update(Buffer.concat([Buffer.from(texto, 'utf8'), Buffer.from([2])])), c.final(), c.getAuthTag()]);
  const rs = Buffer.alloc(4); rs.writeUInt32BE(4096);
  return Buffer.concat([sal, rs, Buffer.from([asPublica.length]), asPublica, cifrado]);
}

const chavePrivada = crypto.createPrivateKey({ key: app.vapid.privada, format: 'jwk' });
function vapid(endpoint) {
  const cab = b64u(JSON.stringify({ typ: 'JWT', alg: 'ES256' }));
  // "aud" = endereço do serviço de avisos (Google, Apple ou Mozilla). O Code node não tem URL(), então recorto o texto.
  const corpo = b64u(JSON.stringify({ aud: (String(endpoint).match(/^https:\/\/[^/]+/) || [''])[0], exp: Math.floor(Date.now() / 1000) + 12 * 3600,
    sub: 'https://webhookn8n6.inovareinteligenciaartificial.com' }));
  const assinatura = crypto.sign('sha256', Buffer.from(cab + '.' + corpo), { key: chavePrivada, dsaEncoding: 'ieee-p1363' });
  return `vapid t=${cab}.${corpo}.${b64u(assinatura)}, k=${app.vapid.publica}`;
}

const mensagem = JSON.stringify({ titulo: pedido.titulo, texto: pedido.texto, url: 'inicio', tag: 'aviso-' + Date.now() });
return inscritos.map(({ chave, sub }) => ({
  json: { chave, endpoint: sub.endpoint, autorizacao: vapid(sub.endpoint) },
  binary: { corpo: { data: criptografa(sub, mensagem).toString('base64'), mimeType: 'application/octet-stream', fileName: 'aviso.bin' } },
}));

// Conta quantos celulares receberam. 201 = entregue; 404/410 = a pessoa desinstalou ou desligou os avisos.
const pedido = $('🧩 Confere a chave e o pedido').first().json;
const envios = $('🔐 Prepara para cada celular').all();
const respostas = $input.all();
let entregues = 0, vencidos = [], falhas = [];
respostas.forEach((r, i) => {
  const st = Number(r.json.statusCode || 0);
  const chave = envios[i] ? envios[i].json.chave : '';
  if (st >= 200 && st < 300) entregues++;
  else if (st === 404 || st === 410) vencidos.push(chave);
  else falhas.push(st || 'erro');
});
let historico = [];
try { historico = JSON.parse($('📖 Lê o histórico de avisos').first().json.historico || '[]'); } catch (e) {}
historico.unshift({ quando: new Date().toISOString(), titulo: pedido.titulo, texto: pedido.texto, entregues, total: respostas.length });
return [{ json: {
  resposta: JSON.stringify({ ok: true, entregues, total: respostas.length, vencidos: vencidos.length, falhas }),
  historico: JSON.stringify(historico.slice(0, 30)), vencidos,
} }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

const r = parseJSON($('🤖 IA redatora de avisos').first().json.output) || {};
const ok = !!(r.titulo && r.texto);
return [{ json: { resposta: JSON.stringify(ok ? { ok, titulo: String(r.titulo).slice(0, 50), texto: String(r.texto).slice(0, 160) } : { ok: false, erro: 'A IA não respondeu agora. Tente de novo.' }) } }];

